package com.smritisathi.app.games;
import android.graphics.Color;import android.os.*;import android.view.*;import android.widget.*;import java.util.*;import com.smritisathi.app.core.*;
public class MemoryMatchActivity extends GameBase {ArrayList<Integer> vals=new ArrayList<>();ArrayList<Button> bs=new ArrayList<>();int first=-1,second=-1,attempts=0,mistakes=0,matched=0;boolean checking=false; @Override public void onCreate(Bundle b){super.onCreate(b);gameHeader("Memory Match","Find all matching pairs");GridLayout g=new GridLayout(this);g.setColumnCount(3);root.addView(g,new LinearLayout.LayoutParams(-1,-2));for(int i=1;i<=6;i++){vals.add(i);vals.add(i);}Collections.shuffle(vals);for(int i=0;i<12;i++){Button x=UI.button(this,"?");x.setTextSize(24);final int k=i;x.setOnClickListener(v->pick(k));bs.add(x);GridLayout.LayoutParams p=new GridLayout.LayoutParams();p.width=0;p.height=120;p.columnSpec=GridLayout.spec(i%3,1,1);p.rowSpec=GridLayout.spec(i/3,1,1);p.setMargins(6,6,6,6);g.addView(x,p);}}void pick(int i){if(checking||bs.get(i).getText().toString().equals("✓")||i==first)return;bs.get(i).setText(String.valueOf(vals.get(i)));if(first<0){first=i;return;}second=i;attempts++;checking=true;new Handler().postDelayed(()->{if(vals.get(first).equals(vals.get(second))){bs.get(first).setText("✓");bs.get(second).setText("✓");matched+=2;if(matched==12){int acc=Math.min(100,(int)Math.round(6.0/Math.max(attempts,6)*100));int dur=(int)Math.round((System.currentTimeMillis()-start)/1000.0);int score=(int)Math.round(acc*.8+Math.max(0,100-dur*.5)*.2);complete("memoryMatch",score,acc,Math.max(1,(dur*1000L)/attempts),dur);}}else{bs.get(first).setText("?");bs.get(second).setText("?");mistakes++;}first=-1;second=-1;checking=false;},800);}}
